/**
 * @name Untrusted JSON reference to JSON schema resolution
 * @description Detects flows from remote sources into referencing.jsonschema APIs that resolve or dereference JSON references
 * @kind path-problem
 * @problem.severity error
 * @id py/referencing-untrusted-jsonschema-resolution
 * @tags security
 *       external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module JsonschemaConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("referencing.jsonschema").getAMember().getACall() and
      sink = call.getArg(0)
    )
  }
}

module JsonschemaFlow = TaintTracking::Global<JsonschemaConfig>;
import JsonschemaFlow::PathGraph

from JsonschemaFlow::PathNode source, JsonschemaFlow::PathNode sink
where JsonschemaFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Untrusted data flows into referencing.jsonschema API $@.", source, "untrusted JSON"
